-- 0023_run_kind.sql  (EPOCH-557)
--
-- What a run was started to do. An analysis runs every enabled stage; an
-- indicator check (Check Again on Indicator Matches) runs only the stage that
-- compares the evidence's entities with an indicator set, against facts an
-- analysis already wrote. A check is its own run, so earlier checks stay
-- and each is shown on its own (board 8). The report isn't regenerated by a
-- check (EPOCH-578), so the app never selects a check run as an analysis.
--
-- Every run before this migration was an analysis: no other kind existed. The
-- default fills those rows, and is then dropped, so every new run states its
-- kind (R35).

ALTER TABLE pipeline_runs
    ADD COLUMN kind TEXT NOT NULL DEFAULT 'analysis'
        CONSTRAINT pipeline_runs_kind_known CHECK (kind IN ('analysis', 'indicator_check'));

ALTER TABLE pipeline_runs ALTER COLUMN kind DROP DEFAULT;
